(* TOTAL chase functions named above: 111. *)

(* ===================================================================== *)
(* CONNECTOR 1 -- COMPLETENESS: the named chase list hides nothing.        *)
(* Every internal function is EITHER chase OR non-chase; the two counts    *)
(* sum to the full internal-function count. So the 111 named above are     *)
(* not a cherry-picked subset -- they are exactly the `true' half of a     *)
(* total classification of all 435 functions.                             *)
(* ===================================================================== *)
Definition nonchase_funcs (p : program) : list ident :=
  map fst (filter (fun idf => negb (fn_chases idf)) (internal_funcs (prog_defs p))).

Lemma filter_partition_length :
  forall (A : Type) (f : A -> bool) (l : list A),
    length (filter f l) + length (filter (fun x => negb (f x)) l) = length l.
Proof.
  induction l as [| a l IH]; simpl; auto.
  destruct (f a); simpl; lia.
Qed.

Lemma chase_nonchase_complete :
  forall p, length (chase_funcs p) + length (nonchase_funcs p) = n_internal p.
Proof.
  intros p. unfold chase_funcs, nonchase_funcs, n_internal.
  rewrite !map_length. apply filter_partition_length.
Qed.

(* ===================================================================== *)
(* CONNECTOR 2 -- MEANINGFULNESS: why this is the RIGHT list to enumerate. *)
(* The value-frame capstone (ActionValueFrame.exec_stmt_value_preserves)   *)
(* is quantified over an ARBITRARY statement, so it applies to EVERY       *)
(* function body. Specialised to a body, it says: any function preserves   *)
(* "Mario's action stays non-flying" (action_sat) GIVEN the decidable,     *)
(* per-body obligation stmt_value_ok (+ the reach hypotheses for its        *)
(* calls). So discharging stmt_value_ok per body is the whole job -- and   *)
(* fn_chases marks EXACTLY the bodies where that obligation needs the       *)
(* pointer-provenance (temp-env INV) argument; the non-chase bodies         *)
(* discharge it from the direct-store frame alone. The enumeration is thus  *)
(* a complete map of the remaining proof burden: 111 need provenance, the   *)
(* other 324 do not.                                                        *)
(* ===================================================================== *)
Corollary body_preserves_action_sat :
  forall (Q : int -> Prop) (bm : block) (ge : genv) (f : function),
    reach_value_preserves Q bm ge ->
    reach_ext_preserves (action_cell bm) ge ->
    forall e le m t le' m' out,
      exec_stmt function_entry2 ge e le m (fn_body f) t le' m' out ->
      Mem.valid_block m bm ->
      action_sat Q m bm ->
      stmt_value_ok Q bm ge e (fn_body f) ->
      Mem.valid_block m' bm /\ action_sat Q m' bm.
Proof.
  intros Q bm ge f Hreach Hext e le m t le' m' out Hexec Hvb Hsat Hok.
  eapply exec_stmt_value_preserves; eauto.
Qed.
